struct Camera { float yaw=0.72f,pitch=0.42f,dist=12; Eigen::Vector3f target=Eigen::Vector3f::Zero(); };
struct Mat4 { float v[16]{}; };
Eigen::Matrix4f eigen(const Mat4&m){Eigen::Matrix4f a;for(int c=0;c<4;c++)for(int r=0;r<4;r++)a(r,c)=m.v[c*4+r];return a;}
Mat4 mul(const Mat4&a,const Mat4&b){ Mat4 o; for(int c=0;c<4;c++)for(int r=0;r<4;r++)for(int k=0;k<4;k++)o.v[c*4+r]+=a.v[k*4+r]*b.v[c*4+k];return o; }
Mat4 perspective(float f,float aspect,float n,float z){Mat4 m;float q=1/std::tan(f/2);m.v[0]=q/aspect;m.v[5]=q;m.v[10]=(z+n)/(n-z);m.v[11]=-1;m.v[14]=2*z*n/(n-z);return m;}
Mat4 view(const Camera&c){ Eigen::Vector3f eye=c.target+Eigen::Vector3f(c.dist*std::cos(c.pitch)*std::sin(c.yaw),-c.dist*std::cos(c.pitch)*std::cos(c.yaw),c.dist*std::sin(c.pitch)); Eigen::Vector3f f=(c.target-eye).normalized(),s=f.cross(Eigen::Vector3f::UnitZ()).normalized(),u=s.cross(f); Mat4 m; m.v[0]=s.x();m.v[4]=s.y();m.v[8]=s.z();m.v[1]=u.x();m.v[5]=u.y();m.v[9]=u.z();m.v[2]=-f.x();m.v[6]=-f.y();m.v[10]=-f.z();m.v[12]=-s.dot(eye);m.v[13]=-u.dot(eye);m.v[14]=f.dot(eye);m.v[15]=1;return m; }
GLuint shader(GLenum type,const char*src){GLuint s=glCreateShader(type);glShaderSource(s,1,&src,nullptr);glCompileShader(s);GLint ok=0;glGetShaderiv(s,GL_COMPILE_STATUS,&ok);if(!ok){char log[2048];glGetShaderInfoLog(s,sizeof log,nullptr,log);throw std::runtime_error(log);}return s;}
GLuint program(){const char*vs="#version 330 core\nlayout(location=0) in vec3 p; layout(location=1) in vec3 normal; uniform mat4 mvp; uniform mat4 model; out vec3 N; void main(){N=transpose(inverse(mat3(model)))*normal;gl_Position=mvp*vec4(p,1);}";const char*fs="#version 330 core\nin vec3 N; out vec4 c; uniform vec4 tint; void main(){float l=.38+.62*max(dot(normalize(N),normalize(vec3(.4,-.5,1))),0.0);c=vec4(tint.rgb*l,tint.a);}";auto a=shader(GL_VERTEX_SHADER,vs),b=shader(GL_FRAGMENT_SHADER,fs);auto p=glCreateProgram();glAttachShader(p,a);glAttachShader(p,b);glLinkProgram(p);glDeleteShader(a);glDeleteShader(b);GLint ok=0;glGetProgramiv(p,GL_LINK_STATUS,&ok);if(!ok){char log[2048];glGetProgramInfoLog(p,sizeof log,nullptr,log);glDeleteProgram(p);throw std::runtime_error(log);}return p;}
